return {"kind":"templates","id":"app-templates","path":"index.html","commit":"0974a62b309b8cf7acd33771b49e9357d4d191f4","lines":{"hobby":[1529,1836],"flight":[1870,2477]},"hobby":[{"name":"Hinged box ⚙","sha256":"9800534e412a18d33a4dfe0dd4a38c6f716d5db1ad512c1e87327cb7af024f2c","code":"// PART: Hinged box (2-part assembly, M3 pin hinge)\n// PRINT: Both parts flat as modeled; no supports; PETG for the hinge\n// NOTE: Hinge pins = 2 short M3 screws (or 3 mm filament); holes 3.4 free-fit\n// NOTE: Assembly view: drag the hinge slider to open the lid\n$fn = 48;\nprint_layout = 1; // 1 = print plate (export this), 0 = app renders single modules\nbox_x = 60;     // box outer length\nbox_y = 40;     // box outer width\nbox_z = 22;     // box outer height\nwall = 2;       // wall thickness\nlid_t = 3;      // lid plate thickness\npil_w = 8;      // hinge pillar width\npil_d = 6;      // hinge pillar depth\nknk_w = 8;      // lid knuckle width\npin_d = 3.4;    // hinge pin hole (M3 free fit)\nhinge_z = 18;   // hinge axis height\n// --- end parameters ---\nmodule tearX(d,l){ // hole along +X with self-supporting 45° roof\n  rotate([90,0,90]) linear_extrude(height=l) union(){\n    circle(d=d);\n    polygon([[-d*0.354, d*0.354],[0, d*0.75],[d*0.354, d*0.354]]);\n  }\n}\nmodule part_base(){\n  difference(){\n    union(){\n      cube([box_x, box_y, box_z]);\n      translate([6, box_y, 0]) cube([pil_w, pil_d, hinge_z + 5]);\n      translate([box_x - 6 - pil_w, box_y, 0]) cube([pil_w, pil_d, hinge_z + 5]);\n    }\n    translate([wall, wall, wall]) cube([box_x - 2*wall, box_y - 2*wall, box_z]);\n    translate([5, box_y + pil_d/2, hinge_z]) tearX(pin_d, box_x - 10);\n  }\n}\nmodule part_lid(){\n  union(){\n    cube([box_x, box_y + pil_d, lid_t]);\n    for(x = [20, box_x - 20 - knk_w]) difference(){\n      translate([x, box_y, lid_t]) cube([knk_w, pil_d, 8]);\n      translate([x - 1, box_y + pil_d/2, lid_t + 4]) tearX(pin_d, knk_w + 2);\n    }\n  }\n}\n// --- assembly ---\n// MODULE: part_base\n// PLACE: part_base t=[0,0,0] r=[0,0,0]\n// MODULE: part_lid\n// PLACE: part_lid t=[60,0,25] r=[0,180,0]\n// JOINT: hinge part_lid origin=[30,43,18] axis=[-1,0,0] range=[0,100] home=0\nif(print_layout){\n  part_base();\n  translate([box_x + 10, 0, 0]) part_lid();\n}\n"},{"name":"Box + snap lid","sha256":"958ec7629d6587c738b58c0ef99ba2055b49014ad3c78986d937c6e069f5f347","code":"// PART: Storage box with friction-fit lid\n// PRINT: Both pieces flat on bed as modeled; no supports; PLA or PETG\n// NOTE: Lid fit uses 0.20 mm/side snug clearance; tune lid_clr for your printer\n$fn = 64;\ninner_x = 60;      // interior length\ninner_y = 40;      // interior width\ninner_z = 25;      // interior depth\nwall = 1.6;        // wall thickness (4 perimeters)\nfloor_t = 1.2;     // floor thickness\nlip_h = 5;         // lid engagement lip height\nlid_clr = 0.20;    // per-side lid clearance (snug fit)\ngap = 10;          // spacing between box and lid on the plate\n// --- end parameters ---\nmodule bottom_chamfer(x,y,c=0.4){ // chamfered footprint pad\n  hull(){ translate([c,c,0]) cube([x-2*c,y-2*c,0.01]); translate([0,0,c]) cube([x,y,0.01]); }\n}\nmodule box(){\n  ox = inner_x + 2*wall; oy = inner_y + 2*wall;\n  difference(){\n    union(){ bottom_chamfer(ox,oy); translate([0,0,0.4]) cube([ox,oy,floor_t+inner_z-0.4]); }\n    translate([wall,wall,floor_t]) cube([inner_x,inner_y,inner_z+1]);\n  }\n}\nmodule lid(){\n  ox = inner_x + 2*wall; oy = inner_y + 2*wall;\n  px = inner_x - 2*lid_clr; py = inner_y - 2*lid_clr;\n  union(){\n    bottom_chamfer(ox,oy);\n    translate([0,0,0.4]) cube([ox,oy,floor_t-0.4]);\n    translate([(ox-px)/2,(oy-py)/2,floor_t]) cube([px,py,lip_h]);\n  }\n}\nbox();\ntranslate([inner_x + 2*wall + gap, 0, 0]) lid();\n"},{"name":"L-bracket","sha256":"c03954eeb729be5958e77ed987c1a344dbf0cfd618c0b633f53b5285854bcba6","code":"// PART: Ribbed 90° L-bracket, M4 mounting\n// PRINT: As modeled (one flange flat on bed); no supports; PETG recommended for load\n// NOTE: Vertical-wall holes are teardropped to self-support; loads should pull the flanges together, in-plane\n$fn = 64;\nleg_a = 50;      // base flange length\nleg_b = 50;      // upright flange height\nwidth = 40;      // bracket width\nthick = 4;       // flange thickness\nrib_t = 3.2;     // gusset rib thickness\nhole_d = 4.5;    // M4 free-fit hole (compensated)\nhole_off = 12;   // hole center distance from corner\nedge_off = 10;   // hole inset from side edges\n// --- end parameters ---\nmodule teardrop(d,l){ // self-supporting horizontal hole, axis along Y\n  rotate([-90,0,0]) union(){\n    cylinder(d=d,h=l);\n    intersection(){ rotate([0,0,45]) cube([d,d,l]); cylinder(d=d*1.6,h=l); }\n  }\n}\ndifference(){\n  union(){\n    cube([leg_a,width,thick]);                       // base flange\n    cube([thick,width,leg_b]);                       // upright flange\n    hull(){ translate([0,(width-rib_t)/2,0]) cube([leg_a*0.75,rib_t,thick]);\n            translate([0,(width-rib_t)/2,0]) cube([thick,rib_t,leg_b*0.75]); } // gusset\n  }\n  for(y=[edge_off,width-edge_off]){\n    translate([hole_off+thick,y,-1]) cylinder(d=hole_d,h=thick+2);            // base holes (vertical: clean)\n    translate([-1,y,hole_off+thick]) teardrop(hole_d,thick+2);                 // upright holes (teardrop)\n  }\n}\n"},{"name":"Wall hook","sha256":"bc076dc7f35c468c094cb5222b231f0f77ebfa704d7c1a85cf0409aef4c43de3","code":"// PART: Flat-back wall hook, screw mounted\n// PRINT: Lying on its side as modeled — layer lines run along the hook for strength; no supports\n// NOTE: Countersunk M4 screw; hook curve is 45°-safe in this orientation\n$fn = 64;\nback_h = 60;     // backplate height\nback_w = 8;      // printed width (Z height on bed)\nback_t = 5;      // backplate thickness off the wall\nhook_r = 14;     // hook inner radius\nhook_t = 7;      // hook material thickness\ntip_h = 12;      // upturned tip height\nscrew_d = 4.5;   // M4 free-fit\ncsk_d = 9;       // countersink diameter\n// --- end parameters ---\nmodule profile(){\n  union(){\n    square([back_t, back_h]);                                            // backplate\n    translate([hook_r+back_t, hook_t/2+2]) circle(d=hook_t);             // root blend\n    difference(){                                                        // hook arc\n      translate([back_t+hook_r,hook_t/2+2]) circle(r=hook_r+hook_t/2);\n      translate([back_t+hook_r,hook_t/2+2]) circle(r=hook_r-hook_t/2);\n      translate([back_t-hook_r*2,hook_t/2+2]) square([hook_r*4,hook_r*2]); // keep lower half\n    }\n    translate([back_t+2*hook_r-hook_t/2,hook_t/2+2]) square([hook_t,tip_h]); // tip\n    translate([back_t+2*hook_r-hook_t/2+hook_t/2,tip_h+hook_t/2+2]) circle(d=hook_t); // rounded tip\n  }\n}\ndifference(){\n  linear_extrude(height=back_w) profile();\n  translate([-1,back_h-14,back_w/2]) rotate([0,90,0])\n    union(){ cylinder(d=screw_d,h=back_t+2); translate([0,0,back_t-2]) cylinder(d1=screw_d,d2=csk_d,h=2.2); }\n}\n"},{"name":"Phone stand","sha256":"5a1329b8d8180d48e94671579d846cdc6e98a35ff86bda749962fdaf1ae2e890","code":"// PART: Phone stand, fixed-angle A-frame\n// PRINT: Lying flat as modeled (extruded profile); no supports; PLA fine\n// NOTE: 63° viewing angle; slot fits phone + case up to slot_w; charge cable passes under the lip gap\n$fn = 64;\nangle = 63;      // phone lean-back angle from horizontal\nslot_w = 14;     // phone slot width (phone + case)\nlip_h = 12;      // front lip height\nrest_l = 95;     // back rest length along the phone\nstand_w = 60;    // stand width (extrusion)\nt = 5;           // material thickness\ncable_gap = 8;   // gap under lip for charging cable\n// --- end parameters ---\nlean = 90 - angle;                       // tilt from vertical\nfoot_x = t + slot_w + sin(lean)*rest_l;  // where the rest tip lands\nbase_l = foot_x + 12;                    // base runs a little past it\nmodule profile(){\n  union(){\n    square([base_l, t]);                                     // base\n    translate([0, t]) square([t, lip_h]);                    // front lip\n    translate([t + slot_w, t]) rotate(-lean) square([t, rest_l]);   // back rest\n    polygon([[t + slot_w + sin(lean)*rest_l*0.45, t],\n             [base_l - 4, t],\n             [t + slot_w + sin(lean)*rest_l*0.45 + t, t + cos(lean)*rest_l*0.35]]);\n  }\n}\ndifference(){\n  linear_extrude(height=stand_w) profile();\n  translate([-1, t, (stand_w-cable_gap*2)/2]) cube([t+2, cable_gap, cable_gap*2]); // cable notch in lip\n}\n"},{"name":"Tube adapter","sha256":"b3515a9f72782156b5aa6ae9881871128e1255398072d03ac63a74fcfe28e4f2","code":"// PART: Round tube/hose adapter (A → B)\n// PRINT: Vertical as modeled; no supports (transition cone auto-limited to ≤45°); PETG for hoses\n// NOTE: Bores are compensated +0.2; barbs omitted — add a hose clamp on soft tubing\n$fn = 64;\nbore_a = 25.2;   // end A inner diameter (fits 25 mm tube, compensated)\nbore_b = 12.2;   // end B inner diameter (fits 12 mm tube, compensated)\nlen_a = 20;      // end A engagement length\nlen_b = 20;      // end B engagement length\nwall = 2.4;      // wall thickness\n// --- end parameters ---\ncone_l = max(abs(bore_a - bore_b)/2 + wall, 6); // ≥45° transition, self-supporting\ndifference(){\n  union(){\n    cylinder(d=bore_a + 2*wall, h=len_a);\n    translate([0,0,len_a]) cylinder(d1=bore_a + 2*wall, d2=bore_b + 2*wall, h=cone_l);\n    translate([0,0,len_a + cone_l]) cylinder(d=bore_b + 2*wall, h=len_b);\n  }\n  translate([0,0,-1]) cylinder(d=bore_a, h=len_a + 1);\n  translate([0,0,len_a - 0.01]) cylinder(d1=bore_a, d2=bore_b, h=cone_l + 0.02);\n  translate([0,0,len_a + cone_l]) cylinder(d=bore_b, h=len_b + 1);\n}\n"},{"name":"Spacer / washer","sha256":"f5c464b6804cf4a545880c66bf0c138c7216f151138f47967c3d5f5291e77a19","code":"// PART: Cylindrical spacer / washer\n// PRINT: Flat on bed; no supports; strongest in compression as printed\n// NOTE: Bore is compensated +0.2 for free fit on the nominal shaft\n$fn = 96;\nouter_d = 12;    // outer diameter\nbore_d = 5.2;    // bore (M5 free fit, compensated)\nheight = 8;      // spacer height\nchamfer = 0.4;   // bottom edge chamfer\n// --- end parameters ---\ndifference(){\n  union(){\n    cylinder(d1=outer_d-2*chamfer, d2=outer_d, h=chamfer);\n    translate([0,0,chamfer]) cylinder(d=outer_d, h=height-chamfer);\n  }\n  translate([0,0,-1]) cylinder(d=bore_d, h=height+2);\n}\n"},{"name":"Cable clip","sha256":"0ff508908db8ac03672c392d78ad9ef8487e54b5c281406a1475aec5751c2d0f","code":"// PART: C-shaped cable clip with screw tab\n// PRINT: Flat as modeled — snap flexure bends in-plane (strong); PETG best for repeated snapping\n// NOTE: Opening is 75% of cable diameter; clip grips cable with clr = 0.15\n$fn = 64;\ncable_d = 8;     // cable diameter to grip\nclip_t = 2.4;    // clip wall thickness\nwidth = 10;      // clip width (Z height on bed)\nclr = 0.15;      // grip clearance\ntab_l = 12;      // screw tab length\nscrew_d = 3.4;   // M3 free-fit\n// --- end parameters ---\nid = cable_d + 2*clr;\nmodule profile(){\n  opening = cable_d*0.75;\n  union(){\n    difference(){\n      circle(d=id+2*clip_t);\n      circle(d=id);\n      translate([-opening/2, 0]) square([opening, id]); // top opening\n    }\n    for(sx=[-1,1]) translate([sx*opening/2, id/2+clip_t/4]) circle(d=clip_t*0.9); // rounded lips\n    translate([-id/2-clip_t-tab_l, -id/2-clip_t]) square([tab_l+id/2, clip_t*1.5]); // tab\n    translate([-id/2-clip_t-tab_l+3, -id/2-clip_t+clip_t*0.75]) circle(d=clip_t*1.5); // tab end round\n  }\n}\ndifference(){\n  linear_extrude(height=width) profile();\n  translate([-id/2-clip_t-tab_l+3, -id/2-clip_t+clip_t*0.75, -1]) cylinder(d=screw_d, h=width+2);\n}\n"},{"name":"Divided tray","sha256":"a13ba89a024b4e47331ed39d4e9b2a4c3a03593e43b0231c75c76479ab3932dc","code":"// PART: Organizer tray with dividers\n// PRINT: Flat on bed; no supports; PLA fine\n// NOTE: Change rows/cols freely — compartments resize automatically\n$fn = 32;\ntray_x = 120;    // outer length\ntray_y = 80;     // outer width\ntray_z = 25;     // outer height\nwall = 1.6;      // outer wall thickness\ndiv_t = 1.2;     // divider thickness (3 perimeters)\nfloor_t = 1.2;   // floor thickness\ncols = 3;        // compartments across X\nrows = 2;        // compartments across Y\n// --- end parameters ---\ncell_x = (tray_x - 2*wall - (cols-1)*div_t)/cols;\ncell_y = (tray_y - 2*wall - (rows-1)*div_t)/rows;\ndifference(){\n  union(){ // body with elephant-foot chamfer\n    hull(){ translate([0.4,0.4,0]) cube([tray_x-0.8,tray_y-0.8,0.01]); translate([0,0,0.4]) cube([tray_x,tray_y,0.01]); }\n    translate([0,0,0.4]) cube([tray_x,tray_y,tray_z-0.4]);\n  }\n  for(cx=[0:cols-1]) for(cy=[0:rows-1])\n    translate([wall + cx*(cell_x+div_t), wall + cy*(cell_y+div_t), floor_t])\n      cube([cell_x, cell_y, tray_z]);\n}\n"},{"name":"Fit coupon 🎯","sha256":"787ed73bfcc4b68efe68d0547f603d0eb7ed02fe4e553f6a262245e78f295ba0","code":"// PART: Clearance calibration coupon (pegs + holes)\n// PRINT: Flat on bed; no supports; print in your usual material\n// NOTE: Pegs are all 5.00 mm. Holes are 5.10/5.20/5.30/5.40/5.50 (notches mark count: 1 notch = 5.10)\n// NOTE: Find the hole that gives a SNUG hand fit -> fit offset = (that hole - 5.20). Enter it in Settings.\n$fn = 48;\nplate_t = 4;     // plate thickness\npeg_d = 5.0;     // peg diameter (constant)\npeg_h = 8;       // peg height\nhole_min = 5.1;  // smallest hole\nhole_step = 0.1; // hole size step\nn = 5;           // number of holes/pegs\npitch = 14;      // spacing\n// --- end parameters ---\nplate_l = pitch*n + 8;\ndifference(){\n  union(){\n    // chamfered plate\n    hull(){ translate([0.4,0.4,0]) cube([plate_l-0.8, 40-0.8, 0.01]); translate([0,0,0.4]) cube([plate_l, 40, 0.01]); }\n    translate([0,0,0.4]) cube([plate_l, 40, plate_t-0.4]);\n    // pegs along the top edge\n    for(i=[0:n-1]) translate([8 + pitch*i + peg_d/2, 30, plate_t]) cylinder(d=peg_d, h=peg_h);\n  }\n  // graded holes along the bottom edge + notch marks (count = index+1)\n  for(i=[0:n-1]){\n    translate([8 + pitch*i + peg_d/2, 12, -1]) cylinder(d=hole_min + hole_step*i, h=plate_t+2);\n    for(k=[0:i]) translate([8 + pitch*i + k*2, 2, plate_t-0.6]) cube([1, 4, 1]);\n  }\n}\n"}],"flight":[{"name":"Nose cone ✈","sha256":"f3e133c14b73ae5a988558c10967375ac6d622ebc271c94bd23721f3d436eff8","sameAs":"tests/templates/nosecone.scad"},{"name":"Centering ring","sha256":"2dd9646994e561dd4a3ea5edba58b3d1428c197533bb821d379eb6c2525f32ef","sameAs":"tests/templates/centering-ring.scad"},{"name":"Av-bay bulkhead","sha256":"16176d39ab224dbd61e57be809e2f1e1e2b64032924c178d0b96ef07ac32d821","code":"// PART: Av-bay ejection bulkhead with face-seal O-ring, 6 in coupler\n// KIND: mechanical\n// MAKE: CNC lathe + 3-axis mill from a 45 mm slice of 152.4 mm 6061-T6 round bar; lathe op1 (bar in chuck): face the seal side, cut the O-ring groove, turn OD 146.20 with the seal-side chamfer, part off; mill op2 (seal face down in soft jaws on the OD): face to 37.70 overall, mill down to the 12.70 plate face around the two bosses, chamfer the top OD edge, bore the two pockets, drill/ream the 10 holes, tap #8-32; inspect OD with micrometer, thickness, groove with gauge rings, holes with GO/NO-GO pins\n// NOTE: Coupler ID 146.30 mm (5.760 in) assumed for a 6 in fibreglass coupler; bulkhead OD 146.20 = ID - 0.10 (5.756 in); measure your coupler and set plate_od = ID - 0.10\n// NOTE: Plate 12.70 = 0.500 in; overall height 37.70 = 1.484 in; bosses 22.00 dia x 25 above the plate at x = +/-40; pockets 16.50 dia x 20 deep (4.3 cm3, about 4 g FFFg black powder each, tape cap) for a printed or PVC charge cup; for 1/2-14 NPT charge caps set pocket_d = 17.86 (45/64 in tap drill) and tap\n// NOTE: O-ring AS568-250, ID 4.984 in = 126.59 mm, W 0.103 in = 2.62 mm, nitrile 70 A (FKM 75 A if the seal sees hot gas). Face seal on the INBOARD (bottom, z=0) face against a stop ring bonded in the coupler: ejection pressure and the rod nuts both push the seal shut. Pressure comes from the OD side (external), so the groove ID equals the O-ring ID per Parker ORD 5700 section 4\n// NOTE: Groove 126.60 ID x 3.10 wide x 1.96 deep, Parker ORD 5700 Design Chart 4-3 face seal for W .103: depth .074-.080 in, width .120-.125 in for vacuum/gases (.140-.146 for liquids), squeeze about 25 %; break groove corners R 0.13-0.38 (.005-.015 in); seal land 0.8 um Ra max, no radial scratches\n// NOTE: Stop ring in the coupler must cover the groove: land ID <= 125 mm, land OD = coupler ID; the 4 rods pass inside it on the 110 bolt circle\n// NOTE: 4 x 6.60 holes = 1/4 in all-thread clearance (6.35 + 0.25) on a 110.00 bolt circle (4.331 in) at 45/135/225/315 deg; 2 x 7.00 holes for a 1/4-20 U-bolt on 44.45 (1.750 in) centres along y; every through hole is INSIDE the seal, so put bonded sealing washers under the rod nuts and the U-bolt nuts or gas bypasses the O-ring\n// NOTE: 2 x 3.20 e-match lead feed-throughs at (+/-6, -40), potted with epoxy after wiring; 2 x #8-32 tapped holes (tap drill #29 = 3.45 mm, 10 deep, modelled at tap drill) on 25.4 centres at y = -50 for a 2-position barrier strip; change tb_pitch/tb_drill for your block\n// NOTE: Recovery shock 5 kN on the U-bolt is tension in the two 1/4-20 legs (122 MPa on the 20.5 mm2 stress area). Declared as bolt_shear per the contract, which checks 0.577*sy and is therefore conservative for a tension load. SPECIFY A STAINLESS A2-70 U-BOLT: a zinc-plated grade-2 steel one (sy 393 MPa) makes only SF 1.86 on that basis. A bent U-bolt's real rating is the vendor's working load, not a material yield: check the tag\n// SPEC-BEGIN\n// {\"name\":\"6 in av-bay ejection bulkhead\",\"size_mm\":[146.2,146.2,37.7],\n//  \"parts\":[{\"name\":\"plate\",\"role\":\"bulkhead disc with face-seal groove, OD chamfers and all through holes\",\"size_mm\":[146.2,146.2,12.7]},\n//           {\"name\":\"charge_well_a\",\"role\":\"charge well boss at +x with the ejection charge pocket\",\"size_mm\":[22,22,27]},\n//           {\"name\":\"charge_well_b\",\"role\":\"charge well boss at -x with the ejection charge pocket\",\"size_mm\":[22,22,27]}],\n//  \"joints\":[{\"a\":\"charge_well_a\",\"b\":\"plate\",\"overlap_mm\":2},{\"a\":\"charge_well_b\",\"b\":\"plate\",\"overlap_mm\":2}],\n//  \"proportions\":[{\"a\":\"charge_well_a\",\"b\":\"plate\",\"axis\":\"z\",\"min\":2.0,\"max\":2.3,\"why\":\"boss stands about 2x the plate thickness so the pocket keeps a 5 mm floor above the plate\"}]}\n// SPEC-END\n// FLIGHT-BEGIN\n// {\"material\":\"6061-T6\",\"process\":\"cnc_lathe\",\"tolerance_class\":\"ISO 2768-m\",\"tess_tol_mm\":0.01,\"hazard\":\"none\",\n//  \"critical\":[{\"name\":\"bulkhead OD\",\"module\":\"plate\",\"axis\":\"x\",\"nominal_mm\":146.20,\"tol_mm\":0.05,\"round\":true,\"tol_src\":\"default\"},\n//              {\"name\":\"bulkhead OD (y)\",\"module\":\"plate\",\"axis\":\"y\",\"nominal_mm\":146.20,\"tol_mm\":0.05,\"round\":true,\"tol_src\":\"default\"},\n//              {\"name\":\"plate thickness\",\"module\":\"plate\",\"axis\":\"z\",\"nominal_mm\":12.70,\"tol_mm\":0.05,\"tol_src\":\"user\"},\n//              {\"name\":\"overall height\",\"module\":\"main\",\"axis\":\"z\",\"nominal_mm\":37.70,\"tol_mm\":0.10,\"tol_src\":\"default\"},\n//              {\"name\":\"boss OD\",\"module\":\"charge_well_a\",\"axis\":\"x\",\"nominal_mm\":22.00,\"tol_mm\":0.10,\"round\":true,\"tol_src\":\"default\"}],\n//  \"bores\":[{\"name\":\"charge pocket A\",\"d_mm\":16.50,\"tol_mm\":0.10,\"at_mm\":[40,0],\"axis\":\"z\",\"from_mm\":17.7,\"to_mm\":37.7,\"tol_src\":\"default\"},\n//           {\"name\":\"charge pocket B\",\"d_mm\":16.50,\"tol_mm\":0.10,\"at_mm\":[-40,0],\"axis\":\"z\",\"from_mm\":17.7,\"to_mm\":37.7,\"tol_src\":\"default\"}],\n//  \"holes\":[{\"name\":\"all-thread rods 1/4 in\",\"d_mm\":6.60,\"tol_mm\":0.10,\"pattern\":\"circle\",\"n\":4,\"bc_d_mm\":110.00,\"start_deg\":45,\"axis\":\"z\",\"from_mm\":0,\"to_mm\":12.7,\"tol_src\":\"default\"},\n//           {\"name\":\"U-bolt 1/4-20\",\"d_mm\":7.00,\"tol_mm\":0.10,\"pattern\":\"list\",\"at_mm\":[[0,22.225],[0,-22.225]],\"axis\":\"z\",\"from_mm\":0,\"to_mm\":12.7,\"tol_src\":\"default\"},\n//           {\"name\":\"e-match feed-through\",\"d_mm\":3.20,\"tol_mm\":0.10,\"pattern\":\"list\",\"at_mm\":[[6,-40],[-6,-40]],\"axis\":\"z\",\"from_mm\":0,\"to_mm\":12.7,\"tol_src\":\"default\"},\n//           {\"name\":\"terminal block #8-32 tap drill\",\"d_mm\":3.45,\"tol_mm\":0.10,\"pattern\":\"list\",\"at_mm\":[[12.7,-50],[-12.7,-50]],\"axis\":\"z\",\"from_mm\":2.7,\"to_mm\":12.7,\"tol_src\":\"default\"}],\n//  \"gauges\":[{\"name\":\"groove GO ring\",\"module\":\"gauge_groove_go\",\"expect\":\"clear\",\"why\":\"groove at least 126.68 ID to 132.72 OD and 1.94 deep everywhere\"},\n//            {\"name\":\"groove ID wall NO-GO\",\"module\":\"gauge_groove_nogo_id\",\"expect\":\"blocked\",\"why\":\"groove ID wall not below 126.52 (O-ring seats on this wall)\"},\n//            {\"name\":\"groove OD wall NO-GO\",\"module\":\"gauge_groove_nogo_od\",\"expect\":\"blocked\",\"why\":\"groove OD wall not above 132.88\"},\n//            {\"name\":\"groove depth NO-GO\",\"module\":\"gauge_groove_nogo_depth\",\"expect\":\"blocked\",\"why\":\"groove floor not deeper than 2.00 (squeeze stays above 22 %)\"}],\n//  \"loads\":[{\"check\":\"bolt_shear\",\"name\":\"U-bolt recovery shock\",\"size\":\"1/4-20\",\"grade\":\"A2-70\",\"n\":2,\"force_N\":5000,\"plate_t_mm\":12.7,\"sf_min\":2.0,\"inputs_src\":\"default\"},\n//           {\"check\":\"thread\",\"name\":\"terminal block screws\",\"size\":\"#8-32\",\"engagement_mm\":10,\"internal_material\":\"6061-T6\",\"sf_min\":2.0,\"inputs_src\":\"default\"}],\n//  \"mfg\":{\"stock\":\"152.4 mm (6.000 in) 6061-T6 round bar, 45 mm slice per bulkhead\",\n//         \"finish\":\"bare or type II clear anodize; seal land and groove 0.8 um Ra (32 uin) max with a circular lay\",\n//         \"heat_treat\":\"none\",\n//         \"deburr\":\"0.5 x 45 chamfer OD both faces, boss top edge and pocket mouth (in the profiles); break hole edges 0.2 max; groove corners R 0.13-0.38 per Parker\",\n//         \"inspect\":[\"OD with micrometer at 2 places 90 deg apart\",\"plate thickness with micrometer at 4 places between holes\",\"groove width and depth with the GO/NO-GO gauge rings or a depth micrometer and pin\",\"rod holes 6.50 GO / 6.70 NO-GO pins, U-bolt holes 6.90 / 7.10, feed-throughs 3.10 / 3.30, pockets 16.40 / 16.60 plug\",\"#8-32 with a 2B thread plug gauge after tapping\"],\n//         \"notes\":[\"Lathe first: OD, seal face and groove in one chucking so the groove is concentric with the OD; the mill then locates on that OD in soft jaws\",\n//                  \"Groove is a finish plunge with a 3.0 mm grooving insert then a sizing pass; do not sand the seal land\",\n//                  \"Tapped holes are drilled 10 deep and tapped 8 deep; the 118 deg drill point adds 1.0 mm beyond the modelled flat bottom\",\n//                  \"Sealing washers (bonded, Dowty type) under every nut on the charge side; pot the feed-throughs with epoxy after wiring\",\n//                  \"Mass about 590 g (217.9 cm3) machined from a 2.2 kg slice; the two 25 mm bosses cost most of the milling time, split-line them as separate turned inserts if the shop prefers\"]}}\n// FLIGHT-END\ntess_tol = 0.01; // max chordal deviation of curved surfaces (mm)\nplate_od = 146.20; // bulkhead OD: coupler ID 146.30 minus 0.10 diametral clearance (5.756 in)\nplate_t = 12.70; // plate thickness, 0.500 in\nod_chamfer = 0.5; // 0.5 x 45 deg chamfer on the OD, both faces (deburr, leads into the coupler)\noring_w = 2.62; // O-ring cross section, AS568 W .103 in\noring_id = 126.59; // O-ring ID, AS568-250 = 4.984 in\ngroove_id = 126.60; // groove ID = O-ring ID (external pressure seats the ring on the ID wall), Parker ORD 5700 sec 4\ngroove_w = 3.10; // groove width, Parker Design Chart 4-3 face seal W .103, vacuum and gases .120-.125 in\ngroove_depth = 1.96; // groove depth, Parker Design Chart 4-3 face seal W .103, .074-.080 in (25 % squeeze on 2.62)\ngroove_tol = 0.04; // groove wall and floor position tolerance per side, Parker +/-.003 in on width and depth, halved per wall\ngroove_od = groove_id + 2*groove_w; // groove OD, derived\nwell_x = 40; // charge well boss centres at +/- this x\nboss_d = 22.00; // charge well boss OD\nboss_h = 25; // boss height above the plate top face\nboss_joint = 2; // boss profile extends this far into the plate so the union is one solid\npocket_d = 16.50; // charge pocket bore, plain, for a printed or PVC charge cup\npocket_depth = 20; // charge pocket depth from the boss top\nboss_chamfer = 0.5; // 0.5 x 45 deg chamfer on the boss top edge and the pocket mouth (deburr)\nrod_hole_d = 6.60; // 1/4 in all-thread clearance: 6.35 plus 0.25\nrod_bc_d = 110.00; // all-thread bolt circle, 4.331 in\nrod_n = 4; // number of all-thread rods\nrod_start_deg = 45; // angle of the first rod hole from +X, keeps them clear of the charge wells\nubolt_hole_d = 7.00; // 1/4-20 U-bolt leg clearance: 6.35 plus 0.65 (hole for a bent leg pair)\nubolt_pitch = 44.45; // U-bolt leg centres, 1.750 in, along y\nfeed_d = 3.20; // e-match lead feed-through, epoxy potted after wiring\nfeed_x = 6; // feed-through holes at +/- this x\nfeed_y = -40; // feed-through holes at this y, between the U-bolt and the terminal block\ntb_drill = 3.45; // #8-32 tap drill, #29 = 0.1360 in\ntb_pitch = 25.4; // terminal block mounting hole centres, 1.000 in\ntb_y = -50; // terminal block screw holes at this y\ntb_depth = 10; // tapped hole depth from the top face (blind: the plate stays sealed)\ncut_ext = 1; // hole cutters overshoot each face by this much so the boolean is clean\n// --- end parameters ---\nfunction fn_tol(d, tol=tess_tol) = max(24, ceil(180 / acos(1 - min(0.5, 2*tol/d))));\n// Plate profile in [r, z], one closed loop: axis, seal face (z=0) with the groove, OD with both chamfers, top face.\nfunction plate_profile() = [\n  [0, 0],\n  [groove_id/2, 0],\n  [groove_id/2, groove_depth],\n  [groove_od/2, groove_depth],\n  [groove_od/2, 0],\n  [plate_od/2 - od_chamfer, 0],\n  [plate_od/2, od_chamfer],\n  [plate_od/2, plate_t - od_chamfer],\n  [plate_od/2 - od_chamfer, plate_t],\n  [0, plate_t]\n];\n// Boss profile in [r, z] about its own axis: starts boss_joint inside the plate, pocket and both chamfers in the profile.\nfunction boss_profile() = let(z0 = plate_t - boss_joint, top = plate_t + boss_h, floor = top - pocket_depth) [\n  [0, z0],\n  [boss_d/2, z0],\n  [boss_d/2, top - boss_chamfer],\n  [boss_d/2 - boss_chamfer, top],\n  [pocket_d/2 + boss_chamfer, top],\n  [pocket_d/2, top - boss_chamfer],\n  [pocket_d/2, floor],\n  [0, floor]\n];\nmodule plate(){ // one revolve, one difference for the ten off-axis holes\n  difference(){\n    rotate_extrude($fn=fn_tol(plate_od)) polygon(plate_profile());\n    union(){\n      for(i=[0:rod_n-1]) rotate(rod_start_deg + i*360/rod_n)\n        translate([rod_bc_d/2, 0, -cut_ext]) cylinder(d=rod_hole_d, h=plate_t + 2*cut_ext, $fn=fn_tol(rod_hole_d));\n      for(sy=[-1, 1]) translate([0, sy*ubolt_pitch/2, -cut_ext]) cylinder(d=ubolt_hole_d, h=plate_t + 2*cut_ext, $fn=fn_tol(ubolt_hole_d));\n      for(sx=[-1, 1]) translate([sx*feed_x, feed_y, -cut_ext]) cylinder(d=feed_d, h=plate_t + 2*cut_ext, $fn=fn_tol(feed_d));\n      for(sx=[-1, 1]) translate([sx*tb_pitch/2, tb_y, plate_t - tb_depth]) cylinder(d=tb_drill, h=tb_depth + cut_ext, $fn=fn_tol(tb_drill));\n    }\n  }\n}\nmodule charge_well(sx){ translate([sx*well_x, 0, 0]) rotate_extrude($fn=fn_tol(boss_d)) polygon(boss_profile()); }\nmodule charge_well_a(){ charge_well(1); }\nmodule charge_well_b(){ charge_well(-1); }\n// Gauge rings for the O-ring groove (intersected with main() by the app; never part of the part).\nmodule gauge_ring(r_in, r_out, z0, z1){ rotate_extrude($fn=fn_tol(2*r_out)) translate([r_in, z0]) square([r_out - r_in, z1 - z0]); }\nmodule gauge_groove_go(){ gauge_ring(groove_id/2 + groove_tol + tess_tol, groove_od/2 - groove_tol - tess_tol, 0.01, groove_depth - groove_tol - tess_tol); }\nmodule gauge_groove_nogo_id(){ gauge_ring(groove_id/2 - groove_tol - 0.001, groove_id/2 + groove_w/4, 0.01, groove_depth/2); }\nmodule gauge_groove_nogo_od(){ gauge_ring(groove_od/2 - groove_w/4, groove_od/2 + groove_tol + 0.001, 0.01, groove_depth/2); }\nmodule gauge_groove_nogo_depth(){ gauge_ring(groove_id/2 + groove_w/4, groove_od/2 - groove_w/4, 0.01, groove_depth + groove_tol + 0.001); }\nmodule main(){ union(){ plate(); charge_well_a(); charge_well_b(); } }\nmain();\n"},{"name":"Fin + TTW tab","sha256":"569e2164007de3734035067be4b2df677cb8e9b3bf7531920fcef1709da3572d","sameAs":"tests/templates/fin.scad"},{"name":"Motor retainer","sha256":"791fdac06696f12e98a6f39a62f36b1444e6a36e72e2d48c056b0964633866ae","sameAs":"tests/templates/motor-retainer.scad"},{"name":"Coupler tube","sha256":"2b8dbd08946af8c5b6be8f4f2284defba021fbc56cada186f7582dc3ce8cc0d4","sameAs":"tests/templates/coupler.scad"},{"name":"Av sled (SLS)","sha256":"ad3ba197dc1e1ae904fe83ae6e934c9ec2872a163c1ce82c2f47ddead626d772","sameAs":"tests/templates/av-sled.scad"}]};
